// src/App.js
import React from 'react';
import './App.css';
import Header from './components/Header';
import Hero from './components/Hero';
import Services from './components/Services';
import HowItWorks from './components/HowItWorks'; // Import new component
import Footer from './components/Footer';
import AnimatedSection from './components/AnimatedSection'; // Import wrapper

function App() {
  return (
    <div className="App">
      <Header />
      <main>
        <Hero />
        <AnimatedSection>
          <Services />
        </AnimatedSection>
        <AnimatedSection>
          <HowItWorks />
        </AnimatedSection>
      </main>
      <Footer />
    </div>
  );
}

export default App;
